    fun t(kod: String, klic: String): String {
        val i = KODY.indexOf(kod).coerceAtLeast(0)
        return T[klic]?.getOrNull(i) ?: T[klic]?.first() ?: klic
    }

    fun t(context: Context, klic: String) = t(Nastaveni(context).jazykNeboCs, klic)
}
